import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Table, Badge, Button, Modal, Form } from 'react-bootstrap';
import { Link } from 'react-router-dom';
import { toast } from 'react-toastify';
import { userAPI } from '../../services/api';

const MyBookings = () => {
  const [bookings, setBookings] = useState([]);
  const [filteredBookings, setFilteredBookings] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');
  const [selectedBooking, setSelectedBooking] = useState(null);
  const [showModal, setShowModal] = useState(false);

  useEffect(() => {
    fetchBookings();
  }, []);

  useEffect(() => {
    filterBookings();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [bookings, filter]);

  const fetchBookings = async () => {
    try {
      setLoading(true);
      console.log('🔍 Fetching user bookings...');
      const response = await userAPI.getMyBookings();
      console.log('📊 MyBookings API response:', response);
      
      // Handle nested response structure
      let bookingsData = response.data;
      if (response.data && response.data.data) {
        bookingsData = response.data.data;
      }
      
      console.log('📋 Bookings data:', bookingsData);
      
      // Ensure bookings is an array
      if (!Array.isArray(bookingsData)) {
        console.warn('⚠️ Bookings data is not an array, setting to empty array');
        bookingsData = [];
      }
      
      setBookings(bookingsData);
    } catch (error) {
      console.error('Error fetching bookings:', error);
      toast.error('Gagal memuat data booking');
      setBookings([]); // Set empty array on error
    } finally {
      setLoading(false);
    }
  };

  const filterBookings = () => {
    // Ensure bookings is an array before filtering
    if (!Array.isArray(bookings)) {
      console.warn('⚠️ Bookings is not an array in filterBookings');
      setFilteredBookings([]);
      return;
    }
    
    if (filter === 'all') {
      setFilteredBookings(bookings);
    } else {
      setFilteredBookings(bookings.filter(booking => booking.status === filter));
    }
  };

  const getStatusBadge = (status) => {
    const variants = {
      pending: 'warning',
      approved: 'success',
      rejected: 'danger'
    };
    return <Badge bg={variants[status]}>{status.toUpperCase()}</Badge>;
  };

  const getTypeBadge = (type) => {
    const variants = {
      room: 'info',
      zoom: 'primary',
      both: 'success'
    };
    const labels = {
      room: 'Ruangan',
      zoom: 'Zoom',
      both: 'Ruangan + Zoom'
    };
    return <Badge bg={variants[type]}>{labels[type]}</Badge>;
  };

  const handleShowDetail = (booking) => {
    console.log('🔍 Selected booking for detail:', booking);
    console.log('📝 Admin notes:', booking.admin_notes);
    console.log('🔗 Zoom notes:', booking.zoom_notes);
    console.log('🏢 Room notes:', booking.room_notes);
    console.log('📋 Full booking object keys:', Object.keys(booking));
    console.log('📋 Admin notes type:', typeof booking.admin_notes);
    console.log('📋 Admin notes length:', booking.admin_notes ? booking.admin_notes.length : 'null/undefined');
    setSelectedBooking(booking);
    setShowModal(true);
  };

  const handleCloseModal = () => {
    setShowModal(false);
    setSelectedBooking(null);
  };

  if (loading) {
    return (
      <div className="text-center py-5">
        <div className="spinner-border" role="status">
          <span className="visually-hidden">Loading...</span>
        </div>
      </div>
    );
  }

  return (
    <Container fluid>
      {/* Header */}
      <Row className="mb-4">
        <Col>
          <h2>Booking Saya</h2>
          <p className="text-muted">Kelola dan lihat status booking Anda</p>
        </Col>
        <Col xs="auto">
          <Button as={Link} to="/user/booking" variant="primary">
            <i className="fas fa-plus me-2"></i>
            Buat Booking Baru
          </Button>
        </Col>
      </Row>

      {/* Filter */}
      <Row className="mb-3">
        <Col>
          <Card className="border-0 shadow-sm">
            <Card.Body className="py-3">
              <Form.Group className="d-flex align-items-center mb-0">
                <Form.Label className="me-3 mb-0">Filter:</Form.Label>
                <Form.Select
                  value={filter}
                  onChange={(e) => setFilter(e.target.value)}
                  style={{ width: 'auto' }}
                >
                  <option value="all">Semua Status</option>
                  <option value="pending">Menunggu</option>
                  <option value="approved">Disetujui</option>
                  <option value="rejected">Ditolak</option>
                </Form.Select>
              </Form.Group>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Bookings Table */}
      <Row>
        <Col>
          <Card>
            <Card.Body>
              {filteredBookings.length > 0 ? (
                <Table responsive hover>
                  <thead>
                    <tr>
                      <th>Judul Acara</th>
                      <th>Tanggal</th>
                      <th>Waktu</th>
                      <th>Jenis</th>
                      <th>Kapasitas</th>
                      <th>Status</th>
                      <th>Aksi</th>
                    </tr>
                  </thead>
                  <tbody>
                    {filteredBookings.map((booking) => (
                      <tr key={booking.id}>
                        <td>
                          <strong>{booking.title}</strong>
                          <br />
                          <small className="text-muted">{booking.purpose}</small>
                        </td>
                        <td>{new Date(booking.date).toLocaleDateString('id-ID')}</td>
                        <td>{booking.start_time} - {booking.end_time}</td>
                        <td>{getTypeBadge(booking.request_type)}</td>
                        <td>{booking.capacity} orang</td>
                        <td>{getStatusBadge(booking.status)}</td>
                        <td>
                          <Button
                            variant="outline-info"
                            size="sm"
                            onClick={() => handleShowDetail(booking)}
                          >
                            <i className="fas fa-eye me-1"></i>
                            Detail
                          </Button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </Table>
              ) : (
                <div className="text-center py-5">
                  <i className="fas fa-calendar-times fa-3x text-muted mb-3"></i>
                  <h5>Tidak ada booking</h5>
                  <p className="text-muted">
                    {filter === 'all' 
                      ? 'Anda belum memiliki booking apapun' 
                      : `Tidak ada booking dengan status "${filter}"`
                    }
                  </p>
                  <Button as={Link} to="/user/booking" variant="primary">
                    Buat Booking Baru
                  </Button>
                </div>
              )}
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Detail Modal */}
      <Modal show={showModal} onHide={handleCloseModal} size="lg">
        <Modal.Header closeButton>
          <Modal.Title>Detail Booking</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {selectedBooking && (
            <Row>
              {console.log('🎭 Rendering modal with selectedBooking:', selectedBooking)}
              {console.log('🎭 Modal admin_notes:', selectedBooking.admin_notes)}
              <Col md={6}>
                <h6>Informasi Acara</h6>
                <Table borderless size="sm">
                  <tbody>
                    <tr>
                      <td><strong>Judul:</strong></td>
                      <td>{selectedBooking.title}</td>
                    </tr>
                    <tr>
                      <td><strong>Tujuan:</strong></td>
                      <td>{selectedBooking.purpose}</td>
                    </tr>
                    <tr>
                      <td><strong>Jenis:</strong></td>
                      <td>{getTypeBadge(selectedBooking.request_type)}</td>
                    </tr>
                    <tr>
                      <td><strong>Status:</strong></td>
                      <td>{getStatusBadge(selectedBooking.status)}</td>
                    </tr>
                  </tbody>
                </Table>
              </Col>
              <Col md={6}>
                <h6>Waktu & Tempat</h6>
                <Table borderless size="sm">
                  <tbody>
                    <tr>
                      <td><strong>Tanggal:</strong></td>
                      <td>{new Date(selectedBooking.date).toLocaleDateString('id-ID')}</td>
                    </tr>
                    <tr>
                      <td><strong>Waktu:</strong></td>
                      <td>{selectedBooking.start_time} - {selectedBooking.end_time}</td>
                    </tr>
                    <tr>
                      <td><strong>Kapasitas:</strong></td>
                      <td>{selectedBooking.capacity} orang</td>
                    </tr>
                    {selectedBooking.room_name && (
                      <tr>
                        <td><strong>Ruangan:</strong></td>
                        <td>{selectedBooking.room_name}</td>
                      </tr>
                    )}
                  </tbody>
                </Table>
              </Col>
              <Col xs={12}>
                <hr />
                <h6>PIC (Person in Charge)</h6>
                <Table borderless size="sm">
                  <tbody>
                    <tr>
                      <td><strong>Nama:</strong></td>
                      <td>
                        {selectedBooking.zoom_approver_name && selectedBooking.room_approver_name ? 
                          `${selectedBooking.zoom_approver_name} (Zoom), ${selectedBooking.room_approver_name} (Room)` :
                          selectedBooking.zoom_approver_name || selectedBooking.room_approver_name || 
                          selectedBooking.pic_name || 'Menunggu approval'
                        }
                      </td>
                    </tr>
                    <tr>
                      <td><strong>Kontak:</strong></td>
                      <td>
                        {selectedBooking.zoom_approver_email && selectedBooking.room_approver_email ? 
                          `${selectedBooking.zoom_approver_email}, ${selectedBooking.room_approver_email}` :
                          selectedBooking.zoom_approver_email || selectedBooking.room_approver_email || 
                          selectedBooking.pic_contact || 'Menunggu approval'
                        }
                      </td>
                    </tr>
                  </tbody>
                </Table>
                
                {selectedBooking.zoom_link && (
                  <>
                    <hr />
                    <h6>Informasi Zoom</h6>
                    <Table borderless size="sm">
                      <tbody>
                        <tr>
                          <td><strong>Link:</strong></td>
                          <td>
                            <a href={selectedBooking.zoom_link} target="_blank" rel="noopener noreferrer">
                              {selectedBooking.zoom_link}
                            </a>
                          </td>
                        </tr>
                        <tr>
                          <td><strong>Meeting ID:</strong></td>
                          <td>{selectedBooking.zoom_meeting_id}</td>
                        </tr>
                        <tr>
                          <td><strong>Passcode:</strong></td>
                          <td>{selectedBooking.zoom_passcode}</td>
                        </tr>
                      </tbody>
                    </Table>
                  </>
                )}

                {selectedBooking.status === 'rejected' && selectedBooking.rejection_reason && (
                  <>
                    <hr />
                    <div className="alert alert-danger">
                      <strong>Alasan Penolakan:</strong><br />
                      {selectedBooking.rejection_reason}
                    </div>
                  </>
                )}

                {selectedBooking.admin_notes && (
                  <>
                    <hr />
                    {console.log('🎯 Rendering admin_notes section:', selectedBooking.admin_notes)}
                    <div className="alert alert-info">
                      <strong>📝 Catatan dari Admin:</strong><br />
                      {selectedBooking.admin_notes}
                    </div>
                  </>
                )}

                {!selectedBooking.admin_notes && console.log('⚠️ Admin notes is falsy:', selectedBooking.admin_notes)}

                {selectedBooking.zoom_notes && (
                  <>
                    <hr />
                    <div className="alert alert-primary">
                      <strong>🔗 Catatan Zoom:</strong><br />
                      {selectedBooking.zoom_notes}
                    </div>
                  </>
                )}

                {selectedBooking.room_notes && (
                  <>
                    <hr />
                    <div className="alert alert-success">
                      <strong>🏢 Catatan Ruangan:</strong><br />
                      {selectedBooking.room_notes}
                    </div>
                  </>
                )}
              </Col>
            </Row>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={handleCloseModal}>
            Tutup
          </Button>
        </Modal.Footer>
      </Modal>
    </Container>
  );
};

export default MyBookings;
